import { createServerClient } from '@supabase/ssr';
import { NextResponse, type NextRequest } from 'next/server';

/**
 * Refreshes the Supabase browser session and copies any updated cookies onto
 * the response generated by the locale proxy.
 */
export async function updateSession(request: NextRequest, response: NextResponse) {
  response.headers.set('Cache-Control', 'private, no-store');
  response.headers.set('Expires', '0');
  response.headers.set('Pragma', 'no-cache');
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value));
          // Forward refreshed cookies to Server Components without losing the
          // locale rewrite or its existing request-header overrides.
          const forwarded = NextResponse.next({ request: { headers: request.headers } });
          response.headers.set('x-middleware-request-cookie', forwarded.headers.get('x-middleware-request-cookie') ?? '');
          const overrides = new Set((response.headers.get('x-middleware-override-headers') ?? '').split(',').filter(Boolean));
          overrides.add('cookie');
          response.headers.set('x-middleware-override-headers', [...overrides].join(','));
          cookiesToSet.forEach(({ name, value, options }) =>
            response.cookies.set(name, value, options)
          );
        },
      },
    }
  );

  // Validates and refreshes the access token without trusting cookie contents.
  await supabase.auth.getClaims();

  return response;
}
